package main

import (
	"github.com/gin-gonic/gin"

	"ginapp/handlers"
	"ginapp/repository"
)

func SetupRouter() *gin.Engine {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	repo := repository.NewUserRepository()
	handlers.RegisterUserRoutes(r, repo)
	return r
}

func main() {
	SetupRouter().Run(":8080")
}

