package repository

type User struct {
	ID           int    `json:"id"`
	Username     string `json:"username"`
	PasswordHash string `json:"passwordHash"`
}

type UserRepository struct {
	users  map[int]User
	nextID int
}

func NewUserRepository() *UserRepository {
	return &UserRepository{users: make(map[int]User), nextID: 1}
}

func (r *UserRepository) Add(username, password string) User {
	u := User{ID: r.nextID, Username: username, PasswordHash: "hash:" + password}
	r.users[u.ID] = u
	r.nextID++
	return u
}

func (r *UserRepository) Get(id int) (User, bool) {
	u, ok := r.users[id]
	return u, ok
}

