package handlers

import (
	"net/http"
	"strconv"

	"github.com/gin-gonic/gin"

	"ginapp/repository"
)

func RegisterUserRoutes(r *gin.Engine, repo *repository.UserRepository) {
	r.POST("/users", func(c *gin.Context) {
		var body struct {
			Username string `json:"username"`
			Password string `json:"password"`
		}
		c.ShouldBindJSON(&body)
		// BUG: returns the repository User, whose PasswordHash field is tagged
		// json:"passwordHash" and leaks straight to the client.
		c.JSON(http.StatusCreated, repo.Add(body.Username, body.Password))
	})

	r.GET("/users/:id", func(c *gin.Context) {
		id, _ := strconv.Atoi(c.Param("id"))
		u, ok := repo.Get(id)
		if !ok {
			c.JSON(http.StatusNotFound, gin.H{"error": "not found"})
			return
		}
		c.JSON(http.StatusOK, u)
	})
}

