package main

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func req(method, path, body string) (int, string) {
	r := SetupRouter()
	var rq *http.Request
	if body == "" {
		rq = httptest.NewRequest(method, path, nil)
	} else {
		rq = httptest.NewRequest(method, path, strings.NewReader(body))
		rq.Header.Set("Content-Type", "application/json")
	}
	w := httptest.NewRecorder()
	r.ServeHTTP(w, rq)
	return w.Code, w.Body.String()
}

func TestNoHashLeak(t *testing.T) {
	code, body := req("POST", "/users", `{"username": "ada", "password": "s3cret"}`)
	if code != http.StatusCreated {
		t.Fatalf("POST /users: %d %s", code, body)
	}
	if strings.Contains(body, "passwordHash") || strings.Contains(body, "hash:") || strings.Contains(body, "s3cret") {
		t.Fatalf("create leaked the hash: %s", body)
	}
	if !strings.Contains(body, "ada") {
		t.Fatalf("create should include username: %s", body)
	}

	// the app uses one shared repo across requests within a SetupRouter call,
	// but each req() builds a fresh router; create+get in one router instead:
	r := SetupRouter()
	w := httptest.NewRecorder()
	r.ServeHTTP(w, mustPost("/users", `{"username": "bob", "password": "hunter2"}`))
	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, httptest.NewRequest("GET", "/users/1", nil))
	if w2.Code != http.StatusOK {
		t.Fatalf("GET /users/1: %d %s", w2.Code, w2.Body.String())
	}
	if strings.Contains(w2.Body.String(), "passwordHash") || strings.Contains(w2.Body.String(), "hash:") {
		t.Fatalf("get leaked the hash: %s", w2.Body.String())
	}
}

func mustPost(path, body string) *http.Request {
	rq := httptest.NewRequest("POST", path, strings.NewReader(body))
	rq.Header.Set("Content-Type", "application/json")
	return rq
}

